def task_func(script_path: str, timeout: int = 60) -> str:
    """
    Execute a specified python code with a given timeout. If the script execution exceeds the timeout, it is terminated.

    Parameters:
    - script_path (str):
    try:
            with open(script_path, 'r') as file:
                script = file.read()
        except FileNotFoundError:
            raise FileNotFoundError(f"File not found: {script_path}")

        try:
            process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except FileNotFoundError:
            raise FileNotFoundError(f"Python not found. Please install Python before running this script.")

        def terminate_process():
            process.terminate()
            process.wait()

        terminate_thread = threading.Thread(target=terminate_process)
        terminate_thread.start()

        try:
            output, error = process.communicate(timeout=timeout)
            if process.returncode == 0:
                return "Script executed successfully."
            else:
                return "Terminating process due to timeout."
        except subprocess.TimeoutExpired:
            terminate_thread.join()
            return "Terminating process due to timeout."

